\xef\xbb\xbfusing System; using System.Collections.Generic; using System.Linq; using System.Text; using System.Numerics; namespace km.gcj.gcj2013.qual { class Program_A { /// <summary> \xe3\x83\x97\xe3\x83\xad\xe3\x82\xb0\xe3\x83\xa9\xe3\x83\xa0\xe3\x81\xae\xe3\x82\xb9\xe3\x82\xbf\xe3\x83\xbc\xe3\x83\x88\xe3\x83\x9d\xe3\x82\xa4\xe3\x83\xb3\xe3\x83\x88 </summary> /// <param name="args"> \xe7\xac\xac\xe4\xb8\x80\xe5\xbc\x95\xe6\x95\xb0\xe3\x81\xab\xe5\x85\xa5\xe5\x8a\x9b\xe3\x83\x95\xe3\x82\xa1\xe3\x82\xa4\xe3\x83\xab\xe3\x82\x92\xe6\x8c\x87\xe5\xae\x9a </param> static void Main(string[] args) { System.Diagnostics.Stopwatch sw = new System.Diagnostics.Stopwatch(); sw.Start(); Logic(args); sw.Stop(); Console.WriteLine(sw.Elapsed); Console.ReadLine(); } private static void Logic(string[] args) { //throw new NotImplementedException(); Problem p = Problem.createProblem(args); if (p == null) { return; } // \xe4\xba\x8b\xe5\x89\x8d\xe8\xa8\x88\xe7\xae\x97\xe3\x82\x92\xe5\xae\x9f\xe8\xa1\x8c preCalc(50); Console.WriteLine(preCalcList.Count-1); // \xe8\xa9\xa6\xe8\xa1\x8c\xe5\x9b\x9e\xe6\x95\xb0\xe3\x82\x92\xe5\x8f\x96\xe5\xbe\x97\xe3\x81\x97\xe3\x80\x81\xe3\x83\xab\xe3\x83\xbc\xe3\x83\x97\xe3\x81\x99\xe3\x82\x8b\xe3\x80\x82 long repeat = p.getNextLineAsInt64Array()[0]; for (int i = 0; i < repeat; i++) { // MainLoop String[] nm = p.getNextStrs().ToArray(); BigInteger start; BigInteger end; if (!BigInteger.TryParse(nm[0],out start)) { throw new Exception(); } if (!BigInteger.TryParse(nm[1], out end)) { throw new Exception(); } int cnt = 0; foreach (var item in preCalcList) { if (start <= item && item <= end) { cnt++; } } // \xef\xbc\xbc(\xe3\x83\xbb\xcf\x89\xe3\x83\xbb\xef\xbc\xbc)\xe3\x80\x80\xe3\x80\x80(\xef\xbc\x8f\xe3\x83\xbb\xcf\x89\xe3\x83\xbb)\xef\xbc\x8f p.WriteAnswerFullLine(cnt.ToString()); } } private static void preCalc(int maxOrder) { // \xe4\xba\x8b\xe5\x89\x8d\xe8\xa8\x88\xe7\xae\x97\xe7\x94\xa8\xe3\x81\xae\xe3\x83\xaa\xe3\x82\xb9\xe3\x83\x88\xe3\x82\x92\xe5\x88\x9d\xe6\x9c\x9f\xe5\x8c\x96 preCalcList = new List<BigInteger>(50000); preCalcList.Add(1*1); preCalcList.Add(2*2); preCalcList.Add(3*3); preCalcList.Add(11*11); preCalcList.Add(22*22); // \xe8\xa8\x88\xe7\xae\x97\xe5\x85\x83\xe3\x81\xae\xe6\x95\xb0\xe5\x80\xa4\xe3\x83\xaa\xe3\x82\xb9\xe3\x83\x88\xe3\x82\x92\xe5\x88\x9d\xe6\x9c\x9f\xe5\x8c\x96 baseNumbersOdd = new List<String>(50000); baseNumbersEven = new List<String>(50000); baseNumbersOdd.Add("0"); baseNumbersOdd.Add("1"); baseNumbersOdd.Add("2"); baseNumbersOdd.Add("3"); baseNumbersEven.Add("00"); baseNumbersEven.Add("11"); baseNumbersEven.Add("22"); for (int order = 3; order <= maxOrder; order++) { Console.WriteLine(order); if (order % 2 == 1) { preCalcSub(baseNumbersOdd, order); } else { preCalcSub(baseNumbersEven, order); } } } private static void preCalcSub(List<String> baseNumbers,int order){ var preCalcList2 = new List<BigInteger>(); var baseNumbers2 = new List<String>(); foreach (String baseNum in new List<String>(baseNumbers)) { String resultNum = baseNum; // \xe8\xbf\xbd\xe5\x8a\xa0\xe3\x81\x99\xe3\x82\x8b\xe6\xa1\x81\xe6\x95\xb0 int addOrder = (order - baseNum.Length) / 2 - 1; for (int i = 0; i < addOrder; i++) { resultNum = "0" + resultNum + "0"; } BigInteger bi1 = check\xe5\xb9\xb3\xe6\x96\xb9\xe5\x9b\x9e\xe6\x96\x87\xe6\x95\xb0("1" + resultNum + "1"); if (bi1 > 0) { preCalcList.Add(bi1); baseNumbers.Add("1" + resultNum + "1"); } BigInteger bi2 = check\xe5\xb9\xb3\xe6\x96\xb9\xe5\x9b\x9e\xe6\x96\x87\xe6\x95\xb0("2" + resultNum + "2"); if (bi2 > 0) { preCalcList2.Add(bi2); baseNumbers2.Add("2" + resultNum + "2"); } } preCalcList.AddRange(preCalcList2); baseNumbers.AddRange(baseNumbers2); return; } /// <summary> /// \xe6\x95\xb0\xe5\xad\x97\xe6\x96\x87\xe5\xad\x97\xe5\x88\x97\xe3\x81\xab\xe5\xaf\xbe\xe3\x81\x97\xe3\x80\x81\xe5\xb9\xb3\xe6\x96\xb9\xe6\x95\xb0\xe3\x81\x8c\xe5\x9b\x9e\xe6\x96\x87\xe6\x95\xb0\xe3\x81\xa7\xe3\x81\x82\xe3\x82\x8b\xe3\x81\x8b\xe3\x82\x92\xe3\x83\x81\xe3\x82\xa7\xe3\x83\x83\xe3\x82\xaf\xe3\x81\x99\xe3\x82\x8b\xe3\x80\x82 /// </summary> /// <param name="num"></param> /// <returns></returns> private static BigInteger check\xe5\xb9\xb3\xe6\x96\xb9\xe5\x9b\x9e\xe6\x96\x87\xe6\x95\xb0(String num) { BigInteger bi; if(!BigInteger.TryParse(num,out bi)){ throw new Exception(); } bi = bi * bi; String numRev = new String(bi.ToString().Reverse().ToArray()); // Console.WriteLine("{0},{1}", bi.ToString(), numRev); if (bi.ToString() == numRev) { return bi; } else { return -1; } } /// <summary> /// \xe4\xba\x8b\xe5\x89\x8d\xe8\xa8\x88\xe7\xae\x97\xe7\x94\xa8\xe3\x81\xae\xe3\x83\xaa\xe3\x82\xb9\xe3\x83\x88 /// </summary> private static List<BigInteger> preCalcList; /// <summary> /// \xe4\xba\x8b\xe5\x89\x8d\xe8\xa8\x88\xe7\xae\x97\xe7\x94\xa8\xe3\x81\xae\xe3\x82\xb5\xe3\x83\x96\xe3\x83\xaa\xe3\x82\xb9\xe3\x83\x88\xef\xbc\x88\xe5\xa5\x87\xe6\x95\xb0\xef\xbc\x89 /// </summary> private static List<String> baseNumbersOdd; /// <summary> /// \xe4\xba\x8b\xe5\x89\x8d\xe8\xa8\x88\xe7\xae\x97\xe7\x94\xa8\xe3\x81\xae\xe3\x82\xb5\xe3\x83\x96\xe3\x83\xaa\xe3\x82\xb9\xe3\x83\x88\xef\xbc\x88\xe5\x81\xb6\xe6\x95\xb0\xef\xbc\x89 /// </summary> private static List<String> baseNumbersEven; } } '